const input = $input.first().json;
const body = input.body || input;
const owner = body.owner || $env.GITHUB_OWNER || '';
const docRepo = body.repo || $env.DESIGN_DOC_REPO || '';
const docPath = body.path || $env.DESIGN_DOC_PATH || '';

const repoName = docRepo.includes('/') ? docRepo.split('/').pop() : docRepo;
const repoOwner = docRepo.includes('/') ? docRepo.split('/')[0] : owner;

if (!repoOwner || !repoName) throw new Error('DESIGN_DOC_REPO가 설정되지 않았습니다.');
if (!docPath) throw new Error('DESIGN_DOC_PATH가 설정되지 않았습니다.');

return [{ json: { owner: repoOwner, repo: repoName, path: docPath } }];

const resp = $input.first().json;
const files = Array.isArray(resp.body) ? resp.body : (Array.isArray(resp) ? resp : []);

if (files.length === 0 || (resp.body && resp.body.message)) {
  const errMsg = (resp.body && resp.body.message) ? resp.body.message : '파일 없음';
  throw new Error('설계 문서 폴더를 읽지 못했습니다: ' + errMsg);
}

const mdFiles = files.filter(f => f.name && f.name.endsWith('.md') && f.type === 'file');
if (mdFiles.length === 0) throw new Error('설계 문서(.md) 파일이 없습니다.');

// 모든 파일 download_url 목록을 단일 아이템으로 반환
return [{ json: { files: mdFiles.map(f => ({ name: f.name, download_url: f.download_url })) } }];

const fileList = $('Filter MD Files').first().json.files || [];
const content = typeof $input.first().json === 'string' ? $input.first().json : JSON.stringify($input.first().json);

// 첫 번째 파일 내용으로 분석
const combined = `## ${fileList[0]?.name || 'design.md'}\n\n${content}`;

const prompt = 'Extract API endpoints, DB tables, and sequence steps from the docs below. Return ONLY JSON:\n{"endpoints":[{"method":"","path":"","description":""}],"tables":[{"name":"","columns":[]}],"sequences":[{"name":"","steps":[]}]}\n\nDocs:\n' + combined.substring(0, 3000);

return [{ json: { model: 'gpt-4.1-mini', messages: [{ role: 'user', content: prompt }], stream: false } }];

const resp = $input.first().json;
const raw = resp.choices?.[0]?.message?.content || '';

if (!raw) {
  return [{ json: {
    agent_id: 'WBS-DDA',
    repo_type: 'design_doc',
    endpoints: [], tables: [], sequences: [],
    error: 'OpenAI 응답 없음'
  } }];
}

let parsed;
try {
  const m = raw.match(/```json\s*([\s\S]*?)```/) || raw.match(/(\{[\s\S]*\})/);
  const jsonStr = m ? (m[1] || m[0]) : '{}';
  parsed = JSON.parse(jsonStr.trim());
} catch (e) {
  parsed = { endpoints: [], tables: [], sequences: [] };
}

return [{ json: {
  agent_id: 'WBS-DDA',
  repo_type: 'design_doc',
  endpoints: parsed.endpoints || [],
  tables: parsed.tables || [],
  sequences: parsed.sequences || [],
  error: null
} }];
